import { fetchWithFallback } from "../utils/fetch";
export const decryptSingleFragmentFactory = (loader, decryptor) => {
    const run = async (key, data, fetchAttempts) => {
        if (!key.uri || !key.iv) {
            return data;
        }
        const { data: keyArrayBuffer } = await fetchWithFallback(key.uri, key.fallbackUri, fetchAttempts, loader.fetchArrayBuffer);
        const decryptedData = await decryptor.decrypt(data, keyArrayBuffer, key.iv);
        return decryptedData;
    };
    return run;
};
