export const STORAGE_WARNING_RATIO = 0.9;
export const STORAGE_WARNING_MIN_AVAILABLE_BYTES = 200 * 1024 * 1024;
export const getStorageStatsFactory = (fs, options) => {
    const run = async () => {
        const snapshot = await fs.getStorageStats();
        const buckets = snapshot.buckets.map((bucket) => {
            const totalFragments = Math.max(0, (bucket.videoLength ?? 0) + (bucket.audioLength ?? 0));
            const averageChunkBytes = bucket.storedChunks > 0
                ? bucket.storedBytes / bucket.storedChunks
                : undefined;
            const expectedBytes = averageChunkBytes !== undefined && totalFragments > 0
                ? averageChunkBytes * totalFragments
                : undefined;
            return {
                id: bucket.id,
                storedBytes: bucket.storedBytes,
                storedChunks: bucket.storedChunks,
                totalFragments,
                averageChunkBytes,
                expectedBytes,
                videoLength: bucket.videoLength,
                audioLength: bucket.audioLength,
                updatedAt: bucket.updatedAt,
            };
        });
        const fragmentBytes = buckets.reduce((sum, bucket) => sum + bucket.storedBytes, 0);
        const subtitlesBytes = snapshot.subtitlesBytes ?? 0;
        const totalUsedBytes = fragmentBytes + subtitlesBytes;
        const usageForAvailable = snapshot.estimate?.usage ?? totalUsedBytes;
        const quotaBytes = snapshot.estimate?.quota;
        const availableBytes = snapshot.estimate?.available ??
            (quotaBytes !== undefined && usageForAvailable !== undefined
                ? Math.max(0, quotaBytes - usageForAvailable)
                : undefined);
        const warningRatio = options?.warningRatio ?? STORAGE_WARNING_RATIO;
        const minAvailableBytes = options?.minAvailableBytes ?? STORAGE_WARNING_MIN_AVAILABLE_BYTES;
        const quotaIsAdvisory = snapshot.estimate?.quotaIsAdvisory ?? false;
        const nearQuota = !quotaIsAdvisory &&
            ((quotaBytes !== undefined &&
                usageForAvailable !== undefined &&
                quotaBytes > 0 &&
                usageForAvailable / quotaBytes >= warningRatio) ||
                (availableBytes !== undefined && availableBytes <= minAvailableBytes));
        return {
            buckets,
            totalUsedBytes,
            quotaBytes,
            availableBytes,
            persisted: snapshot.estimate?.persisted,
            quotaExempt: snapshot.estimate?.quotaExempt ?? false,
            quotaIsAdvisory,
            estimateSource: snapshot.estimate?.source ?? "unknown",
            nearQuota,
            subtitlesBytes,
        };
    };
    return run;
};
