import { sanitizeFilename } from "./sanitize-filename";
// Tab titles are captured while the page is still loading, so they can hold a
// URL or a browser placeholder instead of the real title.
const isUsableTitle = (title) => {
    const trimmed = title?.trim() ?? "";
    if (trimmed.length === 0)
        return false;
    if (/^[a-z]+:\/\//i.test(trimmed))
        return false;
    return !/^(loading|untitled)\b/i.test(trimmed);
};
// CDNs often name playlists with a hash or an opaque id, which is noise in a
// filename. Keep the basename only when it reads like a name.
const isUsableBasename = (name) => {
    if (name.length === 0 || name.length > 40)
        return false;
    if (/^[0-9a-f]{8,}$/i.test(name))
        return false;
    if (/^[0-9]+$/.test(name))
        return false;
    return /[a-z]/i.test(name);
};
const qualityLabel = (level) => {
    if (level.height)
        return `${level.height}p`;
    if (level.bitrate)
        return `${Math.round(level.bitrate / 1000)}kbps`;
    return undefined;
};
export const generateFileName = () => {
    const run = (playlist, level, options) => {
        const path = playlist.uri.split("?")[0];
        const chunks = path.split("/");
        const playlistFilename = chunks[chunks.length - 1];
        const basename = playlistFilename.split(".m3u8")[0];
        const container = options?.container ?? "mp4";
        const title = isUsableTitle(playlist.pageTitle)
            ? sanitizeFilename(playlist.pageTitle)
            : undefined;
        // Prefer the quality over the playlist basename once we have a real title:
        // "My Show-1080p.mp4" beats "My Show-a7f3d91b2c.mp4".
        if (title) {
            const quality = qualityLabel(level);
            const base = quality ? `${title}-${quality}` : title;
            return `${base}.${container}`.normalize("NFC");
        }
        const base = isUsableBasename(basename)
            ? sanitizeFilename(basename)
            : "stream";
        return `${base}.${container}`.normalize("NFC");
    };
    return run;
};
