export class Fragment {
    key;
    uri;
    index;
    fallbackUri;
    byteRange;
    constructor(key, uri, index, fallbackUri, byteRange) {
        this.key = key;
        this.uri = uri;
        this.index = index;
        this.fallbackUri = fallbackUri;
        this.byteRange = byteRange;
    }
}
