import { of } from "rxjs";
import { filter, mergeMap } from "rxjs/operators";
import { levelInspectionsSlice, levelsSlice, playlistPreferencesSlice, playlistsSlice, } from "../store/slices";
export const removePlaylistEpic = (action$) => action$.pipe(filter(playlistsSlice.actions.removePlaylist.match), mergeMap((action) => {
    const playlistID = action.payload.playlistID;
    return of(levelsSlice.actions.removePlaylistLevels({ playlistID }), levelInspectionsSlice.actions.removePlaylistInspections({ playlistID }), playlistPreferencesSlice.actions.removePlaylistPreferences({
        playlistID,
    }));
}));
