import { getFragmentsDetailsFactory } from "./get-fragments-details";
import { generateSubtitleFileName } from "./generate-subtitle-file-name";
import { appendQueryParams } from "../utils/url";
import { fetchWithFallback } from "../utils/fetch";
export const downloadSubtitleTrackFactory = (loader, parser, fs) => {
    const run = async (level, playlist, fetchAttempts, dialog, options = {}) => {
        const baseUri = options.baseUri ?? playlist.uri;
        const fragments = await getFragmentsDetailsFactory(loader, parser)(level, fetchAttempts, {
            baseUri,
        });
        const hasFragments = fragments.length > 0;
        const textParts = [];
        if (hasFragments) {
            for (const fragment of fragments) {
                const { data: fragmentText } = await fetchWithFallback(fragment.uri, fragment.fallbackUri, fetchAttempts, loader.fetchText);
                textParts.push(fragmentText.trim());
            }
        }
        else {
            const levelUri = appendQueryParams(baseUri, level.uri);
            const { data: subtitleText } = await fetchWithFallback(levelUri, level.uri, fetchAttempts, loader.fetchText);
            textParts.push(subtitleText.trim());
        }
        const fileName = generateSubtitleFileName()(playlist, level);
        const download = await fs.prepareTextDownload(textParts.join("\n\n"), "text/vtt");
        await fs.saveAs(fileName, download, { dialog });
        return fileName;
    };
    return run;
};
