import { filter, map } from "rxjs/operators";
import { jobsSlice } from "../store/slices";
export const autoDeleteAfterSaveEpic = (action$, store$) => action$.pipe(filter(jobsSlice.actions.saveAsSuccess.match), filter(() => store$.value.config.autoDeleteAfterSave), map((action) => jobsSlice.actions.delete({ jobId: action.payload.jobId })));
