import { from, of } from "rxjs";
import { catchError, filter, map, mergeMap } from "rxjs/operators";
import { jobsSlice } from "../store/slices";
import { deleteBucketFactory } from "../use-cases";
export const deleteJobEpic = (action$, _store$, { fs }) => action$.pipe(filter(jobsSlice.actions.delete.match), map((action) => action.payload.jobId), mergeMap((jobId) => from(deleteBucketFactory(fs)(jobId)).pipe(catchError(() => of(null)), map(() => jobId))), mergeMap((jobId) => of(jobsSlice.actions.deleteSuccess({ jobId }))));
