import { fetchWithFallback } from "../utils/fetch";
export const downloadSingleFactory = (loader) => {
    const run = async (fragment, fetchAttempts) => {
        const fetcher = (uri, attempts) => fragment.byteRange
            ? loader.fetchArrayBuffer(uri, attempts, fragment.byteRange)
            : loader.fetchArrayBuffer(uri, attempts);
        const { data } = await fetchWithFallback(fragment.uri, fragment.fallbackUri, fetchAttempts, fetcher);
        return data;
    };
    return run;
};
