import { tabs } from "webextension-polyfill";
import { createStore } from "@hls-downloader/core/lib/store/configure-store";
import { playlistsSlice } from "@hls-downloader/core/lib/store/slices";

// A playlist is usually captured before the page sets document.title, so the
// title stored at capture time can be a URL or a placeholder. Keep it in sync.
export function setPlaylistTitleListener(store: ReturnType<typeof createStore>) {
  tabs.onUpdated.addListener((tabId, changeInfo) => {
    const pageTitle = changeInfo.title?.trim();
    if (!pageTitle) {
      return;
    }
    store.dispatch(playlistsSlice.actions.setPlaylistTitle({ tabId, pageTitle }));
  });
}
