import { from, of } from "rxjs";
import { catchError, filter, map, mergeMap } from "rxjs/operators";
import { levelInspectionsSlice } from "../store/slices";
import { inspectLevelEncryptionFactory } from "../use-cases";
export const inspectLevelEpic = (action$, state$, { loader, parser }) => action$.pipe(filter(levelInspectionsSlice.actions.inspect.match), map((action) => action.payload.levelId), mergeMap((levelId) => {
    const level = state$.value.levels.levels[levelId];
    if (!level) {
        return of(levelInspectionsSlice.actions.inspectFailed({
            levelId,
            message: "Level not found",
        }));
    }
    return from(inspectLevelEncryptionFactory(loader, parser)(level, state$.value.config.fetchAttempts, {
        baseUri: level.playlistID,
    })).pipe(map((inspection) => levelInspectionsSlice.actions.inspectSuccess({ inspection })), catchError((error) => of(levelInspectionsSlice.actions.inspectFailed({
        levelId,
        message: error?.message ||
            "Unable to inspect encryption for level",
    }))));
}));
